1	/**
2	 * Every job that runs a project's own commands sets that project's environment up
3	 * first.
4	 *
5	 * The failure this prevents is not a broken build. It is a build that passes for
6	 * the agent and fails in CI, on a machine the agent cannot see, which comes back
7	 * to an engineer who cannot reproduce it -- and to a person held there to judge,
8	 * run by run, whether the pull request can work at all.
9	 *
10	 * Pinned against the generated YAML rather than the `.wac.ts`, because the
11	 * generated file is what an adopter receives and what actually runs. A fourth job
12	 * that runs project commands should fail this test until it includes the step.
13	 */
14	import { describe, expect, test } from "bun:test";
15	import { readFileSync } from "node:fs";
16	
17	const SETUP_STEP = "Run configured environment setup";
18	
19	/** The three jobs, and the step in each that runs what the project declared. */
20	const JOBS = [
21	  {
22	    workflow: "atomaton-runner",
23	    job: "run",
24	    projectCommands: "Run agent",
25	    why: "the agent's own shell, which is the environment every other one is compared against",
26	  },
27	  {
28	    workflow: "atomaton-check",
29	    // The job that runs the project's commands, which is no longer the one a ruleset
30	    // names: that name moved to the job which only collects the verdicts.
31	    job: "pull-request-checks",
32	    projectCommands: "Run this check's commands",
33	    why: "the verdict a pull request merges on",
34	  },
35	  {
36	    workflow: "atomaton-deploy",
37	    job: "deploy",
38	    projectCommands: "Run this deployment's commands",
39	    why: "the least frequent and the most expensive to get wrong",
40	  },
41	] as const;
42	
43	interface WorkflowDocument {
44	  jobs?: Record<string, { steps?: { name?: string; run?: string }[] }>;
45	}
46	
47	function stepNames(workflow: string, job: string): string[] {
48	  const doc = Bun.YAML.parse(
49	    readFileSync(`dist/.github/workflows/${workflow}.yml`, "utf8"),
50	  ) as WorkflowDocument;
51	  const steps = doc.jobs?.[job]?.steps;
52	  expect(steps, `${workflow}.yml has no job named ${job}`).toBeDefined();
53	  return (steps ?? []).map((step) => step.name ?? "");
54	}
55	
56	describe("environment setup reaches every job that runs project commands", () => {
57	  for (const { workflow, job, projectCommands, why } of JOBS) {
58	    test(`${workflow} sets the environment up before "${projectCommands}"`, () => {
59	      const names = stepNames(workflow, job);
60	      const setup = names.indexOf(SETUP_STEP);
61	      const commands = names.indexOf(projectCommands);
62	
63	      expect(setup, `${workflow} runs ${why} without setting the environment up`).toBeGreaterThan(-1);
64	      expect(commands, `${workflow} no longer has a step named "${projectCommands}"`).toBeGreaterThan(-1);
65	      expect(
66	        setup,
67	        `in ${workflow}, setup runs after the commands that need it`,
68	      ).toBeLessThan(commands);
69	    });
70	  }
71	
72	  // Setup runs a project's commands, and a project's commands are not the place
73	  // for a credential nobody asked to expose. In the agent's run this is load
74	  // bearing -- the whole confinement rests on secrets not being in the
75	  // environment when third-party build code runs -- and in the other two it falls
76	  // out of step order. Either way, nothing should quietly add one.
77	  test("setup runs before any secret enters the environment", () => {
78	    for (const { workflow, job } of JOBS) {
79	      const names = stepNames(workflow, job);
80	      const setup = names.indexOf(SETUP_STEP);
81	      const secrets = names.indexOf("Resolve which repository secrets may reach this run");
82	      if (secrets === -1) continue;
83	      expect(setup, `${workflow} resolves secrets before running setup commands`).toBeLessThan(secrets);
84	    }
85	  });
86	
87	  /**
88	   * And no step BEFORE the setup asks for a secret's value.
89	   *
90	   * Steps may run ahead of the setup -- the Atoma CLI install has to, because the
91	   * provider credential check asks that binary and the check itself must come
92	   * first. What none of them may do is put a secret's VALUE in an environment
93	   * block, because from there it reaches `/proc/<pid>/environ`, the log, and every
94	   * process the project's own build code starts.
95	   *
96	   * `${{ secrets.NAME != '' }}` is the boolean GitHub computes, and it is the only
97	   * shape allowed there: a step that needs to know whether a credential exists
98	   * does not need to hold it. The check in `atomaton-runner` is built on exactly
99	   * that distinction, and it is a few characters from the version that is not.
100	   */
101	  test("no step before the setup carries a secret's value", () => {
102	    type WorkflowStep = { name?: string; env?: Record<string, string>; with?: Record<string, string> };
103	    type WorkflowDocument = { jobs?: Record<string, { steps?: WorkflowStep[] }> };
104	
105	    for (const { workflow, job } of JOBS) {
106	      const doc = Bun.YAML.parse(
107	        readFileSync(`dist/.github/workflows/${workflow}.yml`, "utf8"),
108	      ) as WorkflowDocument;
109	      const steps = doc.jobs?.[job]?.steps ?? [];
110	      const setup = steps.findIndex((step) => step.name === SETUP_STEP);
111	      expect(setup, `${workflow}: the setup step`).toBeGreaterThanOrEqual(0);
112	
113	      const offenders: string[] = [];
114	      for (const step of steps.slice(0, setup)) {
115	        for (const [name, value] of Object.entries({ ...step.env, ...step.with })) {
116	          if (!value?.includes("secrets.")) continue;
117	          if (/!=\s*''/.test(value)) continue;
118	          offenders.push(`${workflow}: ${step.name ?? "?"} / ${name} = ${value}`);
119	        }
120	      }
121	      expect(
122	        offenders,
123	        `a step before the environment setup would put a credential's value in its environment. ` +
124	          `Use \`secrets.NAME != ''\` if what it needs is whether the credential exists`,
125	      ).toEqual([]);
126	    }
127	  });
128	});

